import{_ as a,o,c as t,M as e}from"./chunks/framework.b26238a1.js";const s="/assets/image-20220123145828665.0ac1f7c1.png",f=JSON.parse('{"title":"面板插件","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/intro/dashboard.md","filePath":"plugins/intro/dashboard.md"}'),r={name:"plugins/intro/dashboard.md"},i=e('<h1 id="面板插件" tabindex="-1">面板插件 <a class="header-anchor" href="#面板插件" aria-label="Permalink to &quot;面板插件&quot;">​</a></h1><p>不同的用户对图表的展现形式是不一样的。bk-vision以插件的形式来管理图表的展现。</p><p>bk-vision仪表盘（dashboard）都是 由面板插件呈现，内置有</p><ol><li>网格布局面板：gird-layout布局，类似grafana dashboard</li><li>卡片布局面板：卡片栏式布局，面板视图以分栏（如：1<em>1、2</em>2、3*3）、<strong>等高</strong>的形式flex平铺。栏数和高度均可配置。</li><li>自由布局面板：主要为了适配大屏，面板内插件可以任意指定位置、层级。</li><li>报表插件，转为为邮件报表而优化的面板插件。</li><li>瀑布流插件，图表瀑布流展示，主要为了程序图集与富文本。</li></ol><blockquote><p>每一个dashboard包含多个标签(boookMark)，每一个标签都是一个视图集合定义。这里的标签我们可以等价于grafana平台上的dashboard，我们第一期不支持多个标签的话可以设计成单标签 <img src="'+s+'" alt="image-20220123145828665"></p></blockquote>',5),n=[i];function d(l,_,c,p,h,m){return o(),t("div",null,n)}const g=a(r,[["render",d]]);export{f as __pageData,g as default};
